import warp as wpfrom . import collision_driverfrom . import constraintfrom . import smooth_accfrom . import smooth_actuatorfrom . import smooth_muscle_eqfrom . import smooth_frcfrom . import smooth_hunt_crossleyfrom . import smooth_postfrom . import smooth_muscle_cfrom . import smooth_posfrom . import smooth_velfrom . import solverfrom .types import ContactTypefrom .types import Datafrom .types import Modelfrom .warp_util import event_scopewp.set_module_options({"enable_backward": False})@event_scopedef fwd_position(m: Model, d: Data):    """ Position-dependent computations. """    smooth_pos.kinematics(m, d)    smooth_pos.com_pos(m, d)    smooth_pos.crb(m, d)    smooth_pos.factor_m(m, d)    collision_driver.collision(m, d)    constraint.make_constraint(m, d)@event_scopedef fwd_velocity(m: Model, d: Data):    """Velocity-dependent computations."""    smooth_vel.com_vel(m, d)    smooth_vel.site_velocity(m, d)@event_scopedef fwd_muscles(m: Model, d: Data, run_reset: bool):    """ Muscle-related computations. """    if not m.nmuscle:        return    smooth_muscle_eq.compute_act_dot(m, d)    smooth_muscle_c.muscle_path(m, d)    if run_reset:        smooth_muscle_eq.muscle_reset(m, d)    else:        if wp.static(m.opt.muscle_dyn_substeps) > 0:            smooth_muscle_eq.substep_fused(m, d, 1.0)    smooth_muscle_eq.realize_muscle_state(m, d)@event_scopedef fwd_actuators(m: Model, d: Data):    """ Actuator-related computations. """    if not m.nactuator:        return    smooth_actuator.compute_act_dot(m, d)@event_scopedef fwd_forces(m: Model, d: Data):    """ Force-related computations. """    smooth_frc.reset_applied_forces(m, d)    # Passive forces    smooth_frc.apply_passive_forces(m, d)    smooth_frc.rne(m, d)    # Active forces    smooth_muscle_c.apply_muscle_force(m, d)    smooth_actuator.apply_actuator_force(m, d)    if wp.static(m.opt.contact_type == ContactType.HUNT_CROSSLEY):        smooth_hunt_crossley.apply_contact_forces(m, d)    smooth_frc.accumulate_forces(m, d)@event_scopedef fwd_acceleration(m: Model, d: Data, factorize: bool = False):    """ Compute unconstrained acceleration qacc_smooth      factorize: Flag to factorize inertia matrix.    """    if factorize:        smooth_acc.factor_solve_i(m, d, d.qM, d.qLD, d.qacc_smooth,                                  d.qfrc_smooth)    else:        smooth_acc.solve_m(m, d, d.qacc_smooth, d.qfrc_smooth)@event_scopedef post(m: Model, d: Data):    """ Post-processing computations. """    smooth_post.compute_grf(m, d)    smooth_post.compute_limit_torques(m, d)    smooth_post.compute_joint_moments(m, d)@event_scopedef fwd(m: Model, d: Data):    """Forward dynamics (i.e., realize state). No integration """    fwd_position(m, d)    fwd_velocity(m, d)    fwd_muscles(m, d, run_reset=False)    fwd_actuators(m, d)    fwd_forces(m, d)    fwd_acceleration(m, d, factorize=True)    solver.solve(m, d)    post(m, d)@event_scopedef reset(m: Model, d: Data):    """ Called after resetting any of the worlds, realize state """    fwd_position(m, d)    fwd_velocity(m, d)    fwd_muscles(m, d, run_reset=True)  # equilibrate the muscles    fwd_actuators(m, d)    fwd_forces(m, d)    fwd_acceleration(m, d, factorize=True)    solver.solve(m, d)    post(m, d)    d.world_reset.zero_()@event_scopedef fk(m: Model, d: Data):    """ Forward kinematics only for position-dependent quantities """    fwd_position(m, d)